package ktanesolver.module.modded.regular.valves;import static org.assertj.core.api.Assertions.assertThat;import java.util.*;import org.junit.jupiter.api.Test;import ktanesolver.entity.*;import ktanesolver.logic.*;
class ValvesSolverTest{private final ValvesSolver solver=new ValvesSolver();
	@Test void reproducesSerialWalkFixtures(){assertThat(ValvesSolver.walk("ABC123",6)).isEqualTo("100");assertThat(ValvesSolver.walk("A1B2C3",6)).isEqualTo("000");assertThat(ValvesSolver.walk("ZZZ999",27)).isEqualTo("111");assertThat(ValvesSolver.walk("1A2B3C",6)).isEqualTo("000");}
	@Test void appliesSilverThenBlackValveToggles(){ValvesOutput out=solve("ABC123",new ValvesInput(ValvesInput.Material.SILVER,List.of(false,true,false)));assertThat(out.targetCombination()).isEqualTo("100");assertThat(out.finalCombination()).isEqualTo("001");assertThat(out.presses()).containsExactly(3);}
	@Test void zeroDigitSumBypassesMaterialAndColors(){ValvesOutput out=solve("ABCDEF",new ValvesInput(ValvesInput.Material.SILVER,List.of(true,true,true)));assertThat(out.zeroSumOverride()).isTrue();assertThat(out.finalCombination()).isEqualTo("101");assertThat(out.presses()).containsExactly(1,3);}
	@Test void allWhiteAnswerTogglesSameValveTwiceForTwitch(){ValvesOutput out=solve("A1B2C3",new ValvesInput(ValvesInput.Material.BRASS,List.of(false,false,false)));assertThat(out.finalCombination()).isEqualTo("000");assertThat(out.presses()).isEmpty();assertThat(out.twitchToggles()).containsExactly(1,1);}
	@Test void recordsInitialColorsForSouvenir(){BombEntity b=bomb("ABC123");ModuleEntity m=new ModuleEntity();solve(b,m,new ValvesInput(ValvesInput.Material.BRASS,List.of(true,false,true)));assertThat(m.getState().get("valvesInitialState")).isEqualTo("101");}
	@SuppressWarnings("unchecked")private ValvesOutput solve(String serial,ValvesInput i){return solve(bomb(serial),new ModuleEntity(),i);}@SuppressWarnings("unchecked")private ValvesOutput solve(BombEntity b,ModuleEntity m,ValvesInput i){return((SolveSuccess<ValvesOutput>)solver.solve(new RoundEntity(),b,m,i)).output();}private static BombEntity bomb(String serial){BombEntity b=new BombEntity();b.setSerialNumber(serial);return b;}}
